        ok('sub-items muted vs active', await E("getComputedStyle(document.querySelector('.side .nav-in .nav-a:not(.on)')).color !== getComputedStyle(document.querySelector('.side .nav-in .nav-a.on')).color"))
        ok('group headers have icons', await E("document.querySelectorAll('.side .nav-gh .ngi .ic').length === document.querySelectorAll('.side .nav-gh').length"))
