        await pg.locator('[data-ek*=".coop."]').first.click(); await pg.keyboard.press('End'); await pg.keyboard.type(' — بند مضاف أثناء المعاينة'); await pg.wait_for_timeout(200)
        ok('edits stored in report (not records)', await E("App.ui.rpt.ov['rep.title'].v") == 'تقرير الربع الرابع للشراكات' and any('بند مضاف أثناء المعاينة' in (v.get('v','') if isinstance(v,dict) else v) for v in (await E("Object.values(App.ui.rpt.ov)"))))
        ok('records untouched by edits', not await E("D.partnerships.some(p=>JSON.stringify(p).includes('بند مضاف أثناء المعاينة'))"))
        async with pg.expect_download(timeout=90000) as dl:
            await pg.click('[data-rpptx]')
