        ok('pptx contains edits', 'تقرير الربع الرابع للشراكات' in allx and 'بند مضاف أثناء المعاينة' in allx)
        ok('pptx text is RTL', 'rtl="1"' in allx and 'algn="r"' in allx)
        ok('pptx has images (covers/photos)', any(n.startswith('ppt/media/') for n in z.namelist()))
        ok('pptx uses the same font as the preview/PDF', 'IBM Plex Sans Arabic' in allx)
        await E("window.print=()=>{}; 0")
        await pg.click('[data-rpdf]'); await pg.wait_for_timeout(1500)
        await pg.emulate_media(media='print'); await pg.pdf(path='/tmp/rep.pdf', prefer_css_page_size=True, print_background=True); await pg.emulate_media(media='screen')
        await E("window.dispatchEvent(new Event('afterprint'))"); await pg.wait_for_timeout(300)
        pinfo = subprocess.run(['pdfinfo','/tmp/rep.pdf'],capture_output=True,text=True).stdout
        ok('pdf: one 16:9 page per slide', pages('/tmp/rep.pdf') == len(slides) and '960 x 540' in pinfo, pages('/tmp/rep.pdf'))
        txt = subprocess.run(['pdftotext','-f','1','-l','1','/tmp/rep.pdf','-'],capture_output=True,text=True).stdout
        ok('pdf keeps edited title', 'الرابع' in txt)
        ok('print mode cleaned up after printing', await E("!document.documentElement.classList.contains('printing-report') && !document.querySelector('#rptPrint')"))
        # richer sections + data reflection + Ctrl+P
        pid0 = await E("D.partnerships.find(p=>p.title==='المديرية العامة لحرس الحدود').id")
        sid = await E("D.partnerships.find(p=>D.achievements.some(a=>a.partnershipId===p.id)).id")
        await E(f"App.ui.rpt.ids=['{pid0}','{sid}']; App.ui.rpt.sections=RPT_SECTIONS.map(s=>s.k); App.ui.rpt.ov={{}}; location.hash='#/partners'"); await pg.wait_for_timeout(300)
        await go('#/reports', 1500)
        kinds = await E("[...document.querySelectorAll('.rs2')].map(s=>s.dataset.st)")
        ok('report has partner, team, history, activity, overview, exec slides', all(k in kinds for k in ['overview','partner','team','history','activity','cards','exec']), sorted(set(kinds)))
        ok('executive summary text is generated from record data', await E(f"document.querySelector('[data-ek=\"{pid0}.exec\"]').innerText.includes('مذكرة تعاون')"))
        ok('brand centered in sidebar', await E("(()=>{const s=document.querySelector('.side').getBoundingClientRect(), t=document.querySelector('.side .brand-t b').getBoundingClientRect(); return Math.abs((t.left+t.right)/2-(s.left+s.right)/2) < 6})()"))
        ok('no near-empty slides: every content slide has cards', await E("[...document.querySelectorAll('.rs2:not([data-st=cover]):not([data-st=pcover]):not([data-st=end]):not([data-st=story]):not([data-st=hero])')].every(s=>s.querySelectorAll('.rs2-r').length>=4)"))
        first_item = await E(f"(()=>{{const it=itemsOf(D.partnerships.find(p=>p.id==='{pid0}').cooperationAreas)[0]; return it.t? it.t+'\\n'+it.x : it.x}})()")
        await pg.locator(f'[data-ek="{pid0}.coop.0"]').click(); await pg.keyboard.press('End'); await pg.keyboard.type(' (تعديل في التقرير)'); await pg.wait_for_timeout(200)
        ok('edit kept while partnership unchanged', '(تعديل في التقرير)' in await E(f"App.ui.rpt.ov['{pid0}.coop.0'].v"))
        await E(f"(async()=>{{ const p=D.partnerships.find(x=>x.id==='{pid0}'); p.cooperationAreas = '1. بند تعاون محدَّث من سجل الشراكة\\n' + p.cooperationAreas.split('\\n').slice(1).join('\\n'); p.activation='مفعّلة'; await Repo.save('partnerships', p); }})()")
        await go('#/partners', 300); await go('#/reports', 1500)
        t0 = await E(f"document.querySelector('[data-ek=\"{pid0}.coop.0\"]').innerText")
        ok('report reflects the edited partnership (stale edit replaced)', 'بند تعاون محدَّث من سجل الشراكة' in t0 and '(تعديل في التقرير)' not in t0, t0[:60])
        ok('other fields reflected (activation)', 'مفعّلة' in await E("[...document.querySelectorAll('.rs2[data-st=overview] .rs2-t')].map(x=>x.innerText).join(' ')"))
        await E("window.dispatchEvent(new Event('beforeprint'))"); await pg.wait_for_timeout(200)
        ok('Ctrl+P on reports prints the report slides, not the page', await E("document.documentElement.classList.contains('printing-report') && document.querySelectorAll('#rptPrint .rs2').length === document.querySelectorAll('#rpSlides .rs2').length && !document.querySelector('#rptPrint [contenteditable]')"))
        await E("window.dispatchEvent(new Event('afterprint'))"); await pg.wait_for_timeout(200)
        ok('print cleanup', await E("!document.querySelector('#rptPrint')"))
        # themes per design + fullscreen viewer
        await E(f"App.ui.rpt.ids=['{pid0}']; App.ui.rpt.theme='auto'"); 
        for dz, bg in [('board','rgb(247, 244, 236)'), ('classic','rgb(242, 246, 244)')]:
            await E(f"applyDesign('{dz}')"); await pg.wait_for_timeout(600); await go('#/partners', 200); await go('#/reports', 1300)
            got = await E("getComputedStyle(document.querySelector('.rs2[data-st=overview]')).backgroundColor")
            ok(f'report theme follows design: {dz}', got == bg, got)
        await E("applyDesign('board')"); await pg.wait_for_timeout(600); await go('#/partners', 200); await go('#/reports', 1300)
        ok('board headings use Naskh font', 'Noto Naskh' in await E("[...document.querySelectorAll('.rs2[data-st=overview] .rs2-t')].map(x=>getComputedStyle(x).fontFamily).join('|')"))
        async with pg.expect_download(timeout=90000) as dl:
            await pg.click('[data-rpptx]')
        d2 = await dl.value; await d2.save_as('/tmp/rep-board.pptx')
        z2 = zipfile.ZipFile('/tmp/rep-board.pptx'); x2 = ''.join(z2.read(n).decode('utf8') for n in z2.namelist() if re.match(r'ppt/slides/slide\d+\.xml$', n))
        ok('board PowerPoint uses ivory theme + Naskh font', 'F7F4EC' in x2 and 'Noto Naskh Arabic' in x2)
        ok('slides include icon tiles (HTML + PPTX images)', await E("document.querySelectorAll('.rs2 .rs2-ic').length") > 3 and sum(1 for n in z2.namelist() if n.startswith('ppt/media/')) > 3)
        await pg.select_option('#rpTheme', 'classic'); await pg.wait_for_timeout(700)
        ok('manual theme choice overrides design', await E("getComputedStyle(document.querySelector('.rs2[data-st=overview]')).backgroundColor") == 'rgb(242, 246, 244)')
        await pg.select_option('#rpTheme', 'auto'); await pg.wait_for_timeout(500)
        await E("applyDesign('classic')"); await pg.wait_for_timeout(600); await go('#/partners', 200); await go('#/reports', 1200)
        nS = await E("document.querySelectorAll('#rpSlides .rs2').length")
        await pg.click('[data-rshow] >> nth=0'); await pg.wait_for_timeout(800)
        ok('fullscreen viewer opens with all slides', await E("!!document.querySelector('#rptShow') && document.querySelectorAll('#rptShow .rshow-slide').length") == nS)
        await pg.keyboard.press('ArrowLeft'); await pg.keyboard.press('ArrowLeft'); await pg.wait_for_timeout(500)
        ok('arrow keys move forward (RTL)', await E("document.querySelector('.rshow-n').textContent") == f'3 من {nS}')
        await pg.keyboard.press('ArrowRight'); await pg.wait_for_timeout(300)
        ok('arrow back', await E("document.querySelector('.rshow-n').textContent") == f'2 من {nS}')
        await pg.keyboard.press('t'); await pg.wait_for_timeout(300)
        await pg.click('.rshow-th[data-j="4"]'); await pg.wait_for_timeout(400)
        ok('thumbnail jumps to slide', await E("document.querySelector('.rshow-n').textContent") == f'5 من {nS}')
        ok('viewer slides are read-only', await E("!document.querySelector('#rptShow [contenteditable], #rptShow .rs2-t.ed')"))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        ok('Esc closes viewer', await E("!document.querySelector('#rptShow')"))
        # from partnership & register
        pid = await E("D.partnerships.find(p=>p.title==='المديرية العامة لحرس الحدود').id")
        await go(f'#/partnerships/{pid}'); await pg.click('[data-tour="detail-report"]'); await pg.wait_for_timeout(1000)
        ok('report button on partnership opens it preselected', await E("App.ui.rpt.ids.length===1") and (await E("location.hash")).startswith('#/reports'))
        await go('#/partnerships?status=ended'); await pg.click('[data-rep]'); await pg.wait_for_timeout(1000)
        ok('register report uses displayed list', await E("App.ui.rpt.ids.length") == await E("visiblePartnerships().filter(p=>pStatus(p)==='ended').length"))
        # dashboard one page in all designs
        for dz in ['classic','board']:
            await E(f"applyDesign('{dz}')"); await pg.wait_for_timeout(700); await go('#/dashboard?v=alt', 1300)
            await pg.click('[data-print]'); await pg.wait_for_timeout(900)
            await pg.emulate_media(media='print'); await pg.pdf(path=f'/tmp/sheet-{dz}.pdf', prefer_css_page_size=True, print_background=True); await pg.emulate_media(media='screen')
            await E("window.dispatchEvent(new Event('afterprint'))"); await pg.wait_for_timeout(300)
